with parsed as (select id, created_at, coupon_codes, ship_to.zip as ship_zip, ship_to.country as ship_country, size(items) as num_items, array_max(transform(items, x -> x.price)) as max_item_price, coalesce(attributes['utm_source'], 'unknown') as utm_source_or_default from carts where created_at < '2023-05-01') select case when num_items >= 3 then 'LARGE' else 'SMALL' end as num_items_tier, ship_country, (unix_timestamp(max(created_at)) - unix_timestamp(min(created_at))) / 60 as duration_min, sort_array(collect_set(ship_country)) as ship_country_list, round(sum(max_item_price) / nullif(count(case when ship_country = 'UK' then 1 end), 0), 2) as max_item_price_per_uk from parsed group by case when num_items >= 3 then 'LARGE' else 'SMALL' end, ship_country
